        complete: liquidityComplete && !metadataRevealPending,
        nextWorkspace: 'finish',
        endpoint: metadataRevealPending ? '/api/reveal-sealed-metadata' : readiness?.nextEndpoint === '/api/resume-launch' ? '/api/resume-launch' : '/api/create-lp',
